package com.foodresq.matchingservice.client;
public class RecipientResponse{private String id,city,foodCategory,urgencyLevel,status; private Integer quantityRequired; public RecipientResponse(){} public String getId(){return id;} public void setId(String v){id=v;} public String getCity(){return city;} public void setCity(String v){city=v;} public String getFoodCategory(){return foodCategory;} public void setFoodCategory(String v){foodCategory=v;} public String getUrgencyLevel(){return urgencyLevel;} public void setUrgencyLevel(String v){urgencyLevel=v;} public Integer getQuantityRequired(){return quantityRequired;} public void setQuantityRequired(Integer v){quantityRequired=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;}}